package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The sheet's settings (such as the clerk limit) and the roles it assigns user names. */
@Service
public class SettingService {

    /** The key of the clerk limit: the highest due a clerk may settle; no value means no limit. */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The key of the floor: the least a claim's live due can be; the sheet starts at {@link #DEFAULT_FLOOR}. */
    public static final String FLOOR = "floor";

    /** The floor of a sheet that has not set one. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The key of the terms: the days after a claim's date it is due by; the sheet starts at {@link #DEFAULT_TERMS}. */
    public static final String TERMS = "terms";

    /** The terms of a sheet that has not set them, in days. */
    public static final int DEFAULT_TERMS = 14;

    /** The key of the late percent: what an overdue claim gains of its figure for every full 30 days
     *  overdue; the sheet starts at {@link #DEFAULT_LATE_PCT}. */
    public static final String LATE_PCT = "late-pct";

    /** The late percent of a sheet that has not set one. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    private final SheetSettingRepository settings;
    private final SheetRoleRepository roles;
    private final SheetService sheets;
    private final Rollup rollup;
    private final Audit audit;

    public SettingService(SheetSettingRepository settings, SheetRoleRepository roles, SheetService sheets,
            Rollup rollup, Audit audit) {
        this.settings = settings;
        this.roles = roles;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's floor with two decimals: the one it set, else {@link #DEFAULT_FLOOR}. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String sheetId) {
        return floorOf(settings, sheetId);
    }

    /** The sheet's floor as the store holds it, within the caller's transaction. */
    public static BigDecimal floorOf(SheetSettingRepository settings, String sheetId) {
        return settings.findBySheetIdAndKey(sheetId, FLOOR).map((s) -> new BigDecimal(s.getValue()))
                .orElse(DEFAULT_FLOOR);
    }

    /** Set the sheet's floor, kept to two decimals; the live dues it moves are audited after it. */
    @Transactional
    public BigDecimal setFloor(String sheetId, String user, BigDecimal floor) {
        sheets.load(sheetId);
        BigDecimal value = floor.setScale(2);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, FLOOR).orElse(null);
        try {
            if (setting == null) {
                settings.saveAndFlush(new SheetSetting(sheetId, FLOOR, value.toPlainString()));
            } else {
                setting.setValue(value.toPlainString());
                settings.saveAndFlush(setting);
            }
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
        }
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + FLOOR
                + " value=" + value.toPlainString());
        rollup.recordChanges(user, before);
        return value;
    }

    /** The sheet's terms in days: the ones it set, else {@link #DEFAULT_TERMS}. */
    @Transactional(readOnly = true)
    public int terms(String sheetId) {
        return termsOf(settings, sheetId);
    }

    /** The sheet's terms as the store holds them, within the caller's transaction. */
    public static int termsOf(SheetSettingRepository settings, String sheetId) {
        return settings.findBySheetIdAndKey(sheetId, TERMS).map((s) -> Integer.parseInt(s.getValue()))
                .orElse(DEFAULT_TERMS);
    }

    /** Set the sheet's terms, in days. */
    @Transactional
    public int setTerms(String sheetId, String user, int days) {
        sheets.load(sheetId);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, TERMS).orElse(null);
        try {
            if (setting == null) {
                settings.saveAndFlush(new SheetSetting(sheetId, TERMS, Integer.toString(days)));
            } else {
                setting.setValue(Integer.toString(days));
                settings.saveAndFlush(setting);
            }
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
        }
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + TERMS
                + " value=" + days);
        rollup.recordChanges(user, before);
        return days;
    }

    /** The sheet's late percent with two decimals: the one it set, else {@link #DEFAULT_LATE_PCT}. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String sheetId) {
        return latePctOf(settings, sheetId);
    }

    /** The sheet's late percent as the store holds it, within the caller's transaction. */
    public static BigDecimal latePctOf(SheetSettingRepository settings, String sheetId) {
        return settings.findBySheetIdAndKey(sheetId, LATE_PCT).map((s) -> new BigDecimal(s.getValue()))
                .orElse(DEFAULT_LATE_PCT);
    }

    /** Set the sheet's late percent, kept to two decimals; the late charges it moves are audited after it. */
    @Transactional
    public BigDecimal setLatePct(String sheetId, String user, BigDecimal pct) {
        sheets.load(sheetId);
        BigDecimal value = pct.setScale(2);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, LATE_PCT).orElse(null);
        try {
            if (setting == null) {
                settings.saveAndFlush(new SheetSetting(sheetId, LATE_PCT, value.toPlainString()));
            } else {
                setting.setValue(value.toPlainString());
                settings.saveAndFlush(setting);
            }
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
        }
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + LATE_PCT
                + " value=" + value.toPlainString());
        rollup.recordChanges(user, before);
        return value;
    }

    /** The sheet's clerk limit with two decimals, or null when there is no limit. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return settings.findBySheetIdAndKey(sheetId, CLERK_LIMIT).map((s) -> new BigDecimal(s.getValue()))
                .orElse(null);
    }

    /** Set the sheet's clerk limit, kept to two decimals; null clears it, leaving no limit. */
    @Transactional
    public BigDecimal setClerkLimit(String sheetId, String user, BigDecimal limit) {
        sheets.load(sheetId);
        BigDecimal value = limit == null ? null : limit.setScale(2);
        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, CLERK_LIMIT).orElse(null);
        try {
            if (value == null) {
                if (setting != null) {
                    settings.delete(setting);
                    settings.flush();
                }
            } else if (setting == null) {
                settings.saveAndFlush(new SheetSetting(sheetId, CLERK_LIMIT, value.toPlainString()));
            } else {
                setting.setValue(value.toPlainString());
                settings.saveAndFlush(setting);
            }
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
        }
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + CLERK_LIMIT
                + " value=" + (value == null ? "" : value.toPlainString()));
        return value;
    }

    /** The roles the sheet has assigned, by user name; any other name is a clerk. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The role the sheet gives a user name: a clerk unless it was assigned another. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUserName(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** Assign a user name a role on the sheet, replacing the one it had. */
    @Transactional
    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
        sheets.load(sheetId);
        SheetRole assigned = roles.findBySheetIdAndUserName(sheetId, userName).orElse(null);
        if (assigned == null) {
            assigned = new SheetRole(sheetId, userName, role);
        } else {
            assigned.setRole(role);
        }
        SheetRole saved;
        try {
            saved = roles.saveAndFlush(assigned);
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The role was changed by someone else.");
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + userName
                + " role=" + role.label());
        return saved;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class SettingController {

    /** What the screen shows of the sheet's settings; the clerk limit has two decimals, or is null
     *  when there is no limit; the floor has two decimals; the terms are the days after a claim's date
     *  it is due by; the late percent has two decimals. */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, List<RoleView> roles) {
    }

    /** A role the sheet assigns a user name. */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole role) {
            return new RoleView(role.getUserName(), role.getRole().label());
        }
    }

    /** The clerk limit as entered; none means no limit. */
    public record ClerkLimitForm(@DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value) {
    }

    /** The floor as entered. */
    public record FloorForm(@NotNull @DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value) {
    }

    /** The terms as entered: whole days. */
    public record TermsForm(@NotNull @Min(0) @Max(36500) Integer value) {
    }

    /** The late percent as entered. */
    public record LatePctForm(@NotNull @DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value) {
    }

    /** A role to assign a user name, as entered on the form. */
    public record RoleForm(@NotBlank @Size(max = 200) String user, @NotNull String role) {
    }

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @GetMapping("/settings")
    public SettingsView get(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String id = sheetId.trim();
        return view(id, service.clerkLimit(id), service.floor(id));
    }

    /** Set the sheet's clerk limit, or clear it. */
    @PutMapping("/settings/clerk-limit")
    public SettingsView setClerkLimit(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid ClerkLimitForm form) {
        String id = sheetId.trim();
        BigDecimal limit = service.setClerkLimit(id, SignedInUser.name(user), form.value());
        return view(id, limit, service.floor(id));
    }

    /** Set the sheet's floor: the least a claim's live due can be. */
    @PutMapping("/settings/floor")
    public SettingsView setFloor(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid FloorForm form) {
        String id = sheetId.trim();
        BigDecimal floor = service.setFloor(id, SignedInUser.name(user), form.value());
        return view(id, service.clerkLimit(id), floor);
    }

    /** Set the sheet's terms: the days after a claim's date it is due by. */
    @PutMapping("/settings/terms")
    public SettingsView setTerms(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid TermsForm form) {
        String id = sheetId.trim();
        service.setTerms(id, SignedInUser.name(user), form.value());
        return view(id, service.clerkLimit(id), service.floor(id));
    }

    /** Set the sheet's late percent: what an overdue claim gains of its figure for every full 30 days overdue. */
    @PutMapping("/settings/late-pct")
    public SettingsView setLatePct(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid LatePctForm form) {
        String id = sheetId.trim();
        service.setLatePct(id, SignedInUser.name(user), form.value());
        return view(id, service.clerkLimit(id), service.floor(id));
    }

    /** Assign a user name a role on the sheet. */
    @PutMapping("/roles")
    public RoleView setRole(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid RoleForm form) {
        Role role = Role.of(form.role().trim())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST, "No such role."));
        return RoleView.of(service.setRole(sheetId.trim(), SignedInUser.name(user), form.user().trim(), role));
    }

    private SettingsView view(String sheetId, BigDecimal limit, BigDecimal floor) {
        return new SettingsView(limit == null ? null : limit.toPlainString(), floor.toPlainString(),
                service.terms(sheetId), service.latePct(sheetId).toPlainString(), service.roles(sheetId).stream().map(RoleView::of).toList());
    }
}
package net.officefloor.hq.app.setting;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.IdClass;
import jakarta.persistence.Table;
import java.io.Serializable;

/** One of the sheet's settings: its value by key. */
@Entity
@Table(name = "sheet_setting")
@IdClass(SheetSetting.Key.class)
public class SheetSetting {

    public record Key(String sheetId, String key) implements Serializable {
        public Key() {
            this(null, null);
        }
    }

    @Id
    @Column(name = "sheet_id")
    private String sheetId;

    @Id
    @Column(name = "setting_key")
    private String key;

    @Column(name = "setting_value", nullable = false)
    private String value;

    protected SheetSetting() {
    }

    public SheetSetting(String sheetId, String key, String value) {
        this.sheetId = sheetId;
        this.key = key;
        this.value = value;
    }

    public String getKey() {
        return key;
    }

    public String getValue() {
        return value;
    }

    public void setValue(String value) {
        this.value = value;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * The late charge on a claim: an open claim past its due-by (its date plus the sheet's terms) gains
 * the sheet's late percent of its figure for every full 30 days it is overdue, rounded half to even
 * like due; a correction gains none. A statement never binds the charge; it follows the sheet's today until the claim is settled.
 */
public final class LateCharge {

    /** The days a claim must be overdue for each step of the late charge. */
    public static final int DAYS_PER_CHARGE = 30;

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private LateCharge() {
    }

    /** The late charge on the claim of the figure (null: n/a, and no charge) on the sheet's today. */
    public static BigDecimal of(Claim claim, BigDecimal figure, int terms, LocalDate today, BigDecimal latePct) {
        if (figure == null || today == null || claim.getStatus() != ClaimStatus.OPEN || claim.isCorrection()) return ZERO;
        long overdueDays = ChronoUnit.DAYS.between(claim.getDate().plusDays(terms), today);
        long steps = overdueDays <= 0 ? 0 : overdueDays / DAYS_PER_CHARGE;
        if (steps == 0) return ZERO;
        return figure.multiply(latePct).multiply(BigDecimal.valueOf(steps))
                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN);
    }

    /** The figure with its late charge added on top; null when the figure is n/a. */
    public static BigDecimal dueOf(Claim claim, BigDecimal figure, int terms, LocalDate today, BigDecimal latePct) {
        return figure == null ? null : figure.add(of(claim, figure, terms, today, latePct));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Grade;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.setting.SheetSettingRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total (late charges
 * included), and the sheet's
 * claimed-total and due-total. A change takes a snapshot before it alters anything, then
 * {@link #recordChanges} audits, after the change's own lines, each person whose figures moved (in the
 * order they were added) and then the sheet's totals when they moved.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    /** A person's figures; a null due-total is n/a. */
    record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {
        boolean sameAs(Figures other) {
            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal);
        }
    }

    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
    public record Snapshot(String sheetId, Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SheetSettingRepository settings;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SheetSettingRepository settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now, within the caller's transaction. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
        BigDecimal floor = SettingService.floorOf(settings, sheetId);
        int terms = SettingService.termsOf(settings, sheetId);
        BigDecimal latePct = SettingService.latePctOf(settings, sheetId);
        Map<Grade, List<Rate>> ratesByGrade = new LinkedHashMap<>();
        for (Rate rate : rates.findBySheetIdInOrder(sheetId)) {
            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
        }
        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            claimsByPerson.computeIfAbsent(claim.getPersonId(), p -> new ArrayList<>()).add(claim);
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        BigDecimal dueTotal = ZERO;
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            Grade gradeToday = today == null ? null : person.gradeOn(today);
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            boolean keptFigure = false;
            for (Claim claim : claimsByPerson.getOrDefault(person.getId(), List.of())) {
                if (!counts(person, claim)) continue;
                claimed = claimed.add(claim.getAmount());
                // A claim's live figure is at the grade in force on its date.
                Grade grade = person.gradeOn(claim.getDate());
                BigDecimal figure = figure(claim, ratesByGrade.getOrDefault(grade, List.of()), floor);
                BigDecimal owed = LateCharge.dueOf(claim, figure, terms, today, latePct);
                if (owed != null) due = due.add(owed);
                if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) {
                    keptFigure = true;
                }
                // A live figure at a grade other than today's is not undone by today's grade having no rate.
                if (figure != null && grade != gradeToday) keptFigure = true;
            }
            // n/a when no rate of the grade in force today is in force today and no claim keeps a figure.
            BigDecimal personDue = (today == null
                    || inForce(ratesByGrade.getOrDefault(gradeToday, List.of()), today) == null) && !keptFigure
                            ? null : due;
            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue));
            claimedTotal = claimedTotal.add(claimed);
            if (personDue != null) dueTotal = dueTotal.add(personDue);
        }
        return new Snapshot(sheetId, figures, claimedTotal, dueTotal);
    }

    /** Audit, once the transaction commits, the figures that moved since the snapshot was taken. */
    public void recordChanges(String user, Snapshot before) {
        Snapshot after = snapshot(before.sheetId());
        String prefix = " sheet=" + before.sheetId() + " by=" + user;
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + text(now.claimed())
                        + " due-total=" + text(now.dueTotal()));
            }
        });
        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + text(after.claimedTotal())
                    + " due-total=" + text(after.dueTotal()));
        }
    }

    /** Only open and settled claims count toward what is claimed and due; a held person's open claims
     *  do not. */
    private static boolean counts(Person person, Claim claim) {
        return claim.getStatus() == ClaimStatus.SETTLED
                || (claim.getStatus() == ClaimStatus.OPEN && !person.isHeld());
    }

    /** The claim's figure, as ClaimService.figure works it out: the settled due, else the stated due,
     *  else the live due at the grade's rate in force on its date, at least the floor unless a correction;
     *  null when that is n/a. */
    private static BigDecimal figure(Claim claim, List<Rate> gradeRates, BigDecimal floor) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isStated()) return claim.getStatedDue();
        Rate rate = inForce(gradeRates, claim.getDate());
        if (rate == null) return null;
        BigDecimal due = claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN);
        return claim.isCorrection() ? due : due.max(floor);
    }

    /** Of the grade's rates (from the start first, then by from-date), the one in force on the date. */
    private static Rate inForce(List<Rate> gradeRates, LocalDate date) {
        Rate inForce = null;
        for (Rate rate : gradeRates) {
            if (rate.appliesBy(date)) inForce = rate;
        }
        return inForce;
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
    }

    private static String text(BigDecimal figure) {
        return figure == null ? "n/a" : figure.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}

